def json_pointer(doc, pointer: str):
    if pointer == "":
        return doc

    if not pointer.startswith("/"):
        raise ValueError("Non-empty pointer must start with '/'")

    # Split by '/' skipping the first empty segment before the leading '/'
    tokens = pointer.split("/")[1:]

    current = doc
    for token in tokens:
        # Decode '~1' before '~0' according to RFC 6901
        token = token.replace("~1", "/").replace("~0", "~")

        if isinstance(current, dict):
            if token not in current:
                raise ValueError(f"Key '{token}' not found")
            current = current[token]
        elif isinstance(current, list):
            # Must be decimal digits without leading '+' or spaces
            # RFC 6901: index can be "0" or digits not starting with '0'
            if not token.isdigit() or (len(token) > 1 and token.startswith("0")):
                raise ValueError(f"Invalid list index: '{token}'")
            idx = int(token)
            if idx < 0 or idx >= len(current):
                raise ValueError(f"Index out of range: {idx}")
            current = current[idx]
        else:
            raise ValueError(f"Cannot index into non-container type: {type(current).__name__}")

    return current
